import {seedGeneration,connectGeneration} from './generation';import {getActiveCore} from '../../src/adapters/core/current-connection';import {getProjectWriter,studioTabId} from '../../src/features/projects/project-service';import {withDatabase,transact,requestResult} from '../../src/infrastructure/storage/database';import {storedRunDraft,approveRun} from '../../src/application/runs/approval';import {preflightRun,sealRunPlan} from '../../src/application/runs/preflight';import {createRunQueue} from '../../src/application/runs/queue';
export async function seedPendingQueue(){await seedGeneration();connectGeneration();const active=getActiveCore()!,lease=await getProjectWriter('p1'),draft=await withDatabase(undefined,db=>transact(db,['graphs','assets','blobs','diagnostics','runs'],'readonly',tx=>storedRunDraft(tx,'p1',['video-1'],active,true))),checked=preflightRun(draft);if(checked.status!=='ready')throw Error('fixture_plan_blocked');const plan=await sealRunPlan(checked.plan),approved=await approveRun(plan,{confirmed:true,kind:'video',planHash:plan.planHash,nodeCount:1,acknowledgeUnknownFee:true},{...active,lease}),queue=await createRunQueue({projectId:'p1',revision:1,nodeIds:['video-1'],approved},{...active,lease,tabId:studioTabId});return{queueId:queue.queueId,runId:approved.runIds[0]};}
export function pendingQueueState(){return withDatabase(undefined,db=>transact(db,['runs','receipts'],'readonly',async tx=>({runs:await requestResult(tx.objectStore('runs').getAll()),receipts:await requestResult(tx.objectStore('receipts').getAll())})));}
